        Calendar cal = new GregorianCalendar(utc);
        cal.clear();
        cal.set(2021, Calendar.JANUARY, 1, 10, 0, 0);
        System.out.println("before HOUR_OF_DAY=" + cal.get(Calendar.HOUR_OF_DAY));
