        clone.setTimeZone(plusFive);
        System.out.println("after HOUR_OF_DAY=" + clone.get(Calendar.HOUR_OF_DAY));
        System.out.println("millis equal? " + (cal.getTimeInMillis()==clone.getTimeInMillis()));
    }
}
